window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e933ccac62e39c4a"]={"versions": [{"id": "FIG-e933ccac62e39c4a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition benutzerdefinierter Topologie-Elemente im Metamodell des AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>). Es spezifiziert die Spezialisierung generischer Kommunikationsartefakte für anwenderspezifische Bussysteme bzw. Netzwerktechnologien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst abstrakte Basisklassen und deren konkrete Spezialisierungen:</p>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code> (Spezialisierung von <code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Attribute <code>baudrate :PositiveUnlimitedInteger [0..1]</code>, <code>protocolName :String [0..1]</code>, <code>protocolVersion :String [0..1]</code>, <code>speed :Integer [0..1]</code>. Komposition zu <code>PhysicalChannel</code> (<code>+physicalChannel</code>, Kardinalität <code>1..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>).\n</li><li><code>PhysicalChannel</code> (Spezialisierung von <code>Identifiable</code>): Aggregiert bzw. assoziiert über gerichtete Assoziation <code>CommunicationConnector</code> (<code>+commConnector</code>, Kardinalität <code>1..*</code>, Stereotyp <code>«atpVariation»</code>).\n</li><li><code>CommunicationConnector</code> (Spezialisierung von <code>Identifiable</code>): Attribut <code>pncGatewayType :PncGatewayTypeEnum [0..1]</code>. Assoziiert über gerichtete Referenz <code>CommunicationController</code> (<code>+commController</code>, Kardinalität <code>1</code>, Quell-Multiplizität <code>*</code>).\n</li><li><code>CommunicationController</code> (Spezialisierung von <code>Identifiable</code>, Stereotyp <code>«atpVariation»</code>).\n</li><li>Konkrete Ausprägungen: <code>UserDefinedCluster</code> erbt von <code>CommunicationCluster</code>, <code>UserDefinedPhysicalChannel</code> erbt von <code>PhysicalChannel</code>, <code>UserDefinedCommunicationConnector</code> erbt von <code>CommunicationConnector</code>, <code>UserDefinedCommunicationController</code> erbt von <code>CommunicationController</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltenssemantik. Die Beziehungen definieren die Konfigurationshierarchie zur Anbindung von ECUs (über Controller und Connector) an physikalische Kanäle innerhalb eines Kommunikationsclusters inklusive AUTOSAR-Variantenbildung (<code>«atpVariation»</code>, <code>«atpSplitable»</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ermöglicht OEM- oder herstellerspezifische Kommunikationsprotokolle außerhalb der AUTOSAR-Standardbusse (CAN, LIN, FlexRay, Ethernet) im System Description File abzubilden. Relevanz für Codegeneratoren und Konfigurationswerkzeuge bezüglich Bausraten- und Geschwindigkeitsangaben (<code>baudrate</code>, <code>speed</code>) sowie Gateway-Routing für Partial Networking (<code>pncGatewayType</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-580fc51c7e52735b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition benutzerdefinierter Topologie-Elemente im Metamodell des AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>). Es spezifiziert die Spezialisierung generischer Kommunikationsartefakte für anwenderspezifische Bussysteme bzw. Netzwerktechnologien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst abstrakte Basisklassen und deren konkrete Spezialisierungen:</p>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code> (Spezialisierung von <code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Attribute <code>baudrate :PositiveUnlimitedInteger [0..1]</code>, <code>protocolName :String [0..1]</code>, <code>protocolVersion :String [0..1]</code>. Komposition zu <code>PhysicalChannel</code> (<code>+physicalChannel</code>, Kardinalität <code>1..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>).\n</li><li><code>PhysicalChannel</code> (Spezialisierung von <code>Identifiable</code>): Assoziiert über gerichtete Assoziation <code>CommunicationConnector</code> (<code>+commConnector</code>, Kardinalität <code>1..*</code>, Stereotyp <code>«atpVariation»</code>).\n</li><li><code>CommunicationConnector</code> (Spezialisierung von <code>Identifiable</code>): Attribut <code>pncGatewayType :PncGatewayTypeEnum [0..1]</code>. Assoziiert über gerichtete Referenz <code>CommunicationController</code> (<code>+commController</code>, Kardinalität <code>1</code>, Quell-Multiplizität <code>*</code>).\n</li><li><code>CommunicationController</code> (Spezialisierung von <code>Identifiable</code>, Stereotyp <code>«atpVariation»</code>): Attribut <code>wakeUpByControllerSupported :Boolean [0..1]</code>.\n</li><li>Konkrete Ausprägungen: <code>UserDefinedCluster</code> erbt von <code>CommunicationCluster</code>, <code>UserDefinedPhysicalChannel</code> erbt von <code>PhysicalChannel</code>, <code>UserDefinedCommunicationConnector</code> erbt von <code>CommunicationConnector</code>, <code>UserDefinedCommunicationController</code> erbt von <code>CommunicationController</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltenssemantik. Die Beziehungen definieren die Konfigurationshierarchie zur Anbindung von ECUs (über Controller und Connector) an physikalische Kanäle innerhalb eines Kommunikationsclusters inklusive AUTOSAR-Variantenbildung (<code>«atpVariation»</code>, <code>«atpSplitable»</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ermöglicht OEM- oder herstellerspezifische Kommunikationsprotokolle außerhalb der AUTOSAR-Standardbusse (CAN, LIN, FlexRay, Ethernet) im System Description File abzubilden. Relevanz für Codegeneratoren und EcuM/ComM-Konfiguratoren hinsichtlich der Unterstützung von Wake-Up-Fähigkeiten durch den Kommunikations-Controller (<code>wakeUpByControllerSupported</code>) sowie Gateway-Routing für Partial Networking (<code>pncGatewayType</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e933ccac62e39c4a", "to": "FIG-580fc51c7e52735b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Attribut <code>speed :Integer [0..1]</code> wurde entfernt.\n</li><li><code>CommunicationController</code>: Attribut <code>wakeUpByControllerSupported :Boolean [0..1]</code> wurde hinzugefügt.\n</li></ul>"}]};
